$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies @('System.Drawing.Common','System.Drawing.Primitives') -TypeDefinition @'
using System;
using System.Drawing;
public static class SadResidents {
 static double E(double x,double y,double cx,double cy,double rx,double ry){double r=Math.Sqrt(Math.Pow((x-cx)/rx,2)+Math.Pow((y-cy)/ry,2));return Math.Max(0,Math.Min(1,(1-r)/.3));}
 public static Bitmap Make(Bitmap a,Bitmap b,int top,int eye,int mouth){
 Bitmap result=a.Clone(new Rectangle(0,0,512,1280),System.Drawing.Imaging.PixelFormat.Format32bppArgb);
 int dx=0,dy=0;double best=double.MaxValue;
 for(int sy=-8;sy<=8;sy++)for(int sx=-6;sx<=6;sx++){
 double err=0;
 for(int y=eye+14;y<=mouth-16;y++)for(int x=99;x<=121;x++){
 var p=a.GetPixel(146+x,top+y);var q=b.GetPixel(x+sx,y+sy);
 err+=Math.Pow(p.R-q.R,2)+Math.Pow(p.G-q.G,2)+Math.Pow(p.B-q.B,2);
 }
 if(err<best){best=err;dx=sx;dy=sy;}
 }
 for(int y=eye-40;y<=mouth+11;y++)for(int x=56;x<=164;x++){
 double w=0;
 if(y<eye-5){
 foreach(int cx in new[]{84,134})w=Math.Max(w,E(x,y,cx,eye-20,27,19));
 w*=Math.Min(1,(eye-5-y)/2.0);
 }
 if(y>=mouth-3){
 double wm=0;foreach(int cx in new[]{92,128})wm=Math.Max(wm,E(x,y,cx,mouth+1,12,8));
 wm*=Math.Max(0,Math.Min(1,(Math.Abs(x-110)-9)/5.0));
 wm*=Math.Min(1,(y-mouth+3)/2.0);
 w=Math.Max(w,wm);
 }
 if(w<=0)continue;
 var p=a.GetPixel(146+x,top+y);var q=b.GetPixel(x+dx,y+dy);
 result.SetPixel(146+x,top+y,Color.FromArgb(p.A,(int)Math.Round(p.R*(1-w)+q.R*w),(int)Math.Round(p.G*(1-w)+q.G*w),(int)Math.Round(p.B*(1-w)+q.B*w)));
 }
 return result;
 }
 public static int[] Check(Bitmap a,Bitmap b,int top,int eye,int mouth){
 int changed=0,outside=0,alpha=0,eyes=0,nose=0;
 for(int y=0;y<1280;y++)for(int x=0;x<512;x++){
 var p=a.GetPixel(x,y);var q=b.GetPixel(x,y);
 if(p.A!=q.A)alpha++;
 if(p.ToArgb()==q.ToArgb())continue;
 changed++;
 if(x<202||x>310||y<top+eye-40||y>top+mouth+11)outside++;
 if(y>=top+eye-5&&y<=top+eye+12)eyes++;
 if(x>=242&&x<=271&&y>=top+eye+12&&y<=top+mouth-15)nose++;
 }
 return new[]{changed,outside,alpha,eyes,nose};
 }
}
'@
$r='<worktree>'
$p="$r/out/handoff/expression-preview-current"
$d="$p/residents-sad-review"
$items=Get-Content "$d/generation-record.json" -Raw | ConvertFrom-Json
$checks=@()
$font=[Drawing.Font]::new('Malgun Gothic',16)
$small=[Drawing.Font]::new('Malgun Gothic',11)
$sheet=[Drawing.Bitmap]::new(1440,1170);$sg=[Drawing.Graphics]::FromImage($sheet);$sg.Clear([Drawing.Color]::FromArgb(247,243,236))
$n=0
foreach($v in $items){
 $a=[Drawing.Bitmap]::new("$r/content/images/sprite/$($v.id).png")
 $raw=[Drawing.Bitmap]::new($v.raw);$b=[Drawing.Bitmap]::new(220,275);$bg=[Drawing.Graphics]::FromImage($b);$bg.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$bg.DrawImage($raw,0,0,220,275);$bg.Dispose();$raw.Dispose()
 $result=[SadResidents]::Make($a,$b,$v.top,$v.eye,$v.mouth)
 $result.Save("$p/sad/$($v.id)__sad-preview.png")
 $q=[SadResidents]::Check($a,$result,$v.top,$v.eye,$v.mouth)
 if($q[1]+$q[2]+$q[3]+$q[4] -ne 0){throw "Preservation check failed: $($v.id)"}
 $checks += [pscustomobject]@{id=$v.id;changedPixels=$q[0];outsideExpressionChanges=$q[1];alphaChanges=$q[2];originalEyeBandChanges=$q[3];noseChanges=$q[4];sourceHash=(Get-FileHash "$r/content/images/sprite/$($v.id).png" -Algorithm SHA256).Hash;resultHash=(Get-FileHash "$p/sad/$($v.id)__sad-preview.png" -Algorithm SHA256).Hash;gameIntegrated=$false}
 $c=[Drawing.Bitmap]::new(720,390);$g=[Drawing.Graphics]::FromImage($c);$g.Clear([Drawing.Color]::FromArgb(247,243,236));$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
 $g.DrawString("$($v.name) · 원본",$font,[Drawing.Brushes]::Black,10,8);$g.DrawString('슬픔 시안',$font,[Drawing.Brushes]::Black,370,8)
 $src=[Drawing.Rectangle]::new(170,$v.top+66,168,155)
 $g.DrawImage($a,[Drawing.Rectangle]::new(10,50,336,310),$src,[Drawing.GraphicsUnit]::Pixel);$g.DrawImage($result,[Drawing.Rectangle]::new(370,50,336,310),$src,[Drawing.GraphicsUnit]::Pixel)
 $c.Save("$d/$($v.id)-comparison.png")
 $sg.DrawImageUnscaled($c,($n%2)*720,[int][Math]::Floor($n/2)*390)
 $g.Dispose();$c.Dispose();$a.Dispose();$b.Dispose();$result.Dispose();$n++
}
$sheet.Save("$d/six-comparisons.png");$sg.Dispose();$sheet.Dispose()
$checks | ConvertTo-Json -Depth 5 | Set-Content "$d/pixel-check.json" -Encoding utf8
$checks | Select-Object id,changedPixels,outsideExpressionChanges,alphaChanges,originalEyeBandChanges,noseChanges | Format-Table
# Eight-person overview, retaining the latest two shamans.
$all=@(@{id='mudang_f';name='여자 무당';top=157},@{id='mudang_m';name='남자 무당';top=78})+@($items)
$c=[Drawing.Bitmap]::new(1280,740);$g=[Drawing.Graphics]::FromImage($c);$g.Clear([Drawing.Color]::FromArgb(247,243,236));$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
$n=0
foreach($v in $all){
