$selected=Get-Content "$p/sad-eight-review/selected-assets.json" -Raw | ConvertFrom-Json
$checks=@()
foreach($v in $geo){
 $a=[Drawing.Bitmap]::new("$p/residents-sad-texture/$($v.id)-before.png")
 $s=$selected | Where-Object id -eq $v.id
 $raw=[Drawing.Bitmap]::new($s.selectedPath)
 $b=[Drawing.Bitmap]::new(220,275);$g=[Drawing.Graphics]::FromImage($b)
