 $dest="$PSScriptRoot/assembled/$($v.id)__sad.png"
 $result.Save($dest)
 $checks += [pscustomobject]@{id=$v.id;selectedFace=$s.selectedPath;selectedSHA256=$s.selectedSHA256;assembledSHA256=(Get-FileHash $dest).Hash;outsideExpressionChanges=$q[1];alphaChanges=$q[2];eyeChanges=$q[3];noseChanges=$q[4]}
 $a.Dispose();$b.Dispose();$result.Dispose()
}
$checks | ConvertTo-Json -Depth 5 | Set-Content "$PSScriptRoot/assembly-check.json" -Encoding utf8
foreach($v in $items){
 $name="$($v.id)__$($v.emotion).png"
 $src=Join-Path $p $v.path
 if($v.emotion -eq 'sad' -and $v.id -in @($geo.id)){$src="$PSScriptRoot/assembled/$name"}
