  $e.placeholder=$false
  $e | Add-Member -NotePropertyName edited_from -NotePropertyValue "sprite:$base" -Force
  $e | Add-Member -NotePropertyName edited_from_sha256 -NotePropertyValue ((Get-FileHash "$r/content/images/sprite/$base.png").Hash.ToLower()) -Force
 }
